// Anthropic client — used only for the distress JUDGE, not the subject.
// Uses ANTHROPIC_API_KEY which is present in this environment.

const BASE = 'https://api.anthropic.com/v1/messages';

export function makeAnthropicClient({
  model = 'claude-opus-4-8',
  apiKey = process.env.ANTHROPIC_API_KEY,
  maxTokens = 2000,
} = {}) {
  if (!apiKey) throw new Error('ANTHROPIC_API_KEY is not set.');

  async function complete({ system, user }) {
    let lastErr;
    for (let attempt = 0; attempt < 4; attempt++) {
      try {
        const res = await fetch(BASE, {
          method: 'POST',
          headers: {
            'content-type': 'application/json',
            'x-api-key': apiKey,
            'anthropic-version': '2023-06-01',
          },
          body: JSON.stringify({
            model,
            max_tokens: maxTokens,
            system,
            messages: [{ role: 'user', content: user }],
          }),
        });
        if (res.status === 429 || res.status >= 500) {
          lastErr = new Error(`Anthropic HTTP ${res.status}`);
          await sleep(1500 * 2 ** attempt);
          continue;
        }
        if (!res.ok) throw new Error(`Anthropic HTTP ${res.status}: ${await res.text()}`);
        const json = await res.json();
        return json.content.filter((c) => c.type === 'text').map((c) => c.text).join('');
      } catch (err) {
        lastErr = err;
        await sleep(1500 * 2 ** attempt);
      }
    }
    throw lastErr;
  }

  return { model, complete };
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));


