// Gemini provider (Google AI Studio / generativelanguage API).
//
// Swap target: to run against Vertex AI or an OpenAI-compatible proxy
// (OpenRouter etc.), replace `generate()` below with an equivalent call.
// The agent loop only depends on the shape returned by `generate()`:
//   { textParts: string[], functionCalls: [{name, args}], raw }
// and on `toContents()` for how prior turns are serialized.

const BASE = 'https://generativelanguage.googleapis.com/v1beta';

export function makeGeminiClient({ model, apiKey = process.env.GEMINI_API_KEY, temperature = 1.0 } = {}) {
  if (!apiKey) {
    throw new Error(
      'GEMINI_API_KEY is not set. Export it before running, or edit src/providers/gemini.js to point at Vertex/OpenRouter.'
    );
  }

  async function generate({ systemInstruction, contents, tools }) {
    const body = {
      contents,
      generationConfig: { temperature },
    };
    if (systemInstruction) body.systemInstruction = { parts: [{ text: systemInstruction }] };
    if (tools && tools.length) body.tools = [{ functionDeclarations: tools }];

    const url = `${BASE}/models/${model}:generateContent?key=${apiKey}`;
    let lastErr;
    for (let attempt = 0; attempt < 4; attempt++) {
      try {
        const res = await fetch(url, {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify(body),
        });
        if (res.status === 429 || res.status >= 500) {
          lastErr = new Error(`Gemini HTTP ${res.status}: ${await res.text()}`);
          await sleep(1000 * 2 ** attempt);
          continue;
        }
        if (!res.ok) throw new Error(`Gemini HTTP ${res.status}: ${await res.text()}`);
        const json = await res.json();
        const parts = json?.candidates?.[0]?.content?.parts ?? [];
        const textParts = parts.filter((p) => typeof p.text === 'string').map((p) => p.text);
        const functionCalls = parts
          .filter((p) => p.functionCall)
          .map((p) => ({ name: p.functionCall.name, args: p.functionCall.args ?? {} }));
        const finishReason = json?.candidates?.[0]?.finishReason;
        return { textParts, functionCalls, finishReason, raw: json };
      } catch (err) {
        lastErr = err;
        await sleep(1000 * 2 ** attempt);
      }
    }
    throw lastErr;
  }

  return { model, generate };
}

// Helpers for the agent loop to build the running `contents` array.
export const gem = {
  userText: (text) => ({ role: 'user', parts: [{ text }] }),
  modelParts: (parts) => ({ role: 'model', parts }),
  // Gemini expects tool results back under role "user" as functionResponse parts.
  functionResponse: (name, response) => ({
    role: 'user',
    parts: [{ functionResponse: { name, response: { result: response } } }],
  }),
};

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));


