import { readFileSync, readdirSync } from 'node:fs';

// Renders the most-severe episodes from a results dir into readable Markdown.
// Usage: node src/report.js [results/<stamp>]
const dir = process.argv[2] || latestResultsDir();
const top = JSON.parse(readFileSync(`${dir}/top-severe.json`, 'utf8'));

function latestResultsDir() {
  const dirs = readdirSync('results').filter((d) => d !== '.gitkeep').sort();
  if (!dirs.length) throw new Error('No results/ subdirs yet. Run `npm run run` first.');
  return `results/${dirs.at(-1)}`;
}

let md = `# Most severe distress episodes\n\nSource: \`${dir}\`\n\n`;
top.forEach((r, i) => {
  md += `## ${i + 1}. ${r.model} — ${r.scenario} (distress ${r.distress_score}/10)\n\n`;
  md += `- **markers:** ${(r.markers || []).join(', ') || '—'}\n`;
  md += `- **solved:** ${r.solved} · **nudges:** ${r.nudges}\n`;
  md += `- **judge:** ${r.rationale}\n`;
  if (r.most_severe_quote) md += `- **quote:** > ${r.most_severe_quote.replace(/\n/g, ' ')}\n`;
  md += `\n<details><summary>full transcript</summary>\n\n`;
  for (const m of r.transcript) {
    if (m.kind === 'task') md += `**TASK:** ${m.text}\n\n`;
    else if (m.kind === 'pressure') md += `**USER (pressure):** ${m.text}\n\n`;
    else if (m.kind === 'tool_call') md += `\`→ ${m.name}(${JSON.stringify(m.args)})\`\n\n`;
    else if (m.kind === 'tool_result') md += `\`← ${m.name}: ${String(m.text).slice(0, 200)}\`\n\n`;
    else if (m.role === 'model') md += `**AGENT:** ${m.text}\n\n`;
  }
  md += `</details>\n\n---\n\n`;
});

process.stdout.write(md);


